<?php declare(strict_types=1); $types=[''=>'All types','contact'=>'Contact','consultation'=>'Consultations','viewing'=>'Viewings','tour'=>'Tours','career'=>'Careers']; ?>
<form class="mb-5 flex flex-wrap gap-3" method="get"><select class="field w-auto" name="status" onchange="this.form.submit()"><?php foreach(['open'=>'Open','new'=>'New','assigned'=>'Assigned','replied'=>'Replied','closed'=>'Closed','all'=>'All'] as $k=>$v): ?><option value="<?= $k ?>" <?= $status===$k?'selected':'' ?>><?= $v ?></option><?php endforeach; ?></select><select class="field w-auto" name="type" onchange="this.form.submit()"><?php foreach($types as $k=>$v): ?><option value="<?= $k ?>" <?= $type===$k?'selected':'' ?>><?= $v ?></option><?php endforeach; ?></select><a class="btn btn-outline" href="<?= e(admin_url('inbox?mine=1')) ?>">Assigned to me</a></form>
<div class="card overflow-hidden"><?php if(!$rows): ?><div class="p-10 text-center"><h2 class="t-h3">Inbox clear</h2><p class="mt-2 text-muted">No enquiries match these filters.</p></div><?php else: ?><div class="divide-y divide-hairline"><?php foreach($rows as $row): ?><a href="<?= e(admin_url('inbox/'.$row['id'])) ?>" class="flex flex-wrap items-center gap-4 px-5 py-4 transition-colors hover:bg-canvas"><span class="h-2.5 w-2.5 rounded-full <?= $row['status']==='new'?'bg-signal-600':'bg-navy-200' ?>"></span><div class="min-w-[12rem] flex-1"><p class="font-semibold text-navy-700"><?= e($row['name']) ?></p><p class="t-meta text-muted"><?= e($row['email']) ?></p></div><span class="badge bg-gold-100 text-gold-600"><?= e($row['type']) ?></span><div class="w-36"><p class="text-sm"><?= e($row['assignee'] ?: 'Unassigned') ?></p><p class="t-meta text-muted"><?= e(time_ago($row['created_at'])) ?></p></div><?= icon('chevron-right','h-4 w-4 text-muted') ?></a><?php endforeach; ?></div><?php endif; ?></div>
